// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    bool private __entered;
    uint256 private __reentryAmount;

    // This test contract itself is the re-entrant recipient (c pays msg.sender).
    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.withdraw(__reentryAmount);
        }
    }

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 4);
        __entered = false;
        vm.deal(address(c), amount * 2);
        __reentryAmount = amount;
        uint256 before = address(c).balance;

        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        // Rule: a successful withdraw(amount) must remove exactly `amount` from c;
        // a reverted one must remove nothing.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}
